import Component from 'flarum/common/Component';
import Alert from 'flarum/common/components/Alert';
export default class CriterionStatus extends Component {
  view() {
    const criterion = this.attrs.criterion;
    if (!criterion) return;
    const messages = [];
    if (criterion.isValid()) {
      messages.push(m(Alert, {
        type: "success",
        dismissible: false
      }, app.translator.trans('askvortsov-auto-moderator.admin.criterion_status.valid')));
    } else {
      messages.push(m(Alert, {
        type: "error",
        dismissible: false
      }, app.translator.trans('askvortsov-auto-moderator.admin.criterion_status.invalid')));
    }
    const actionValidation = criterion.invalidActionSettings();
    if (actionValidation && Object.keys(actionValidation).length) {
      messages.push(m(Alert, {
        type: "error",
        dismissible: false
      }, app.translator.trans('askvortsov-auto-moderator.admin.criterion_status.action_validation_errors'), m("div", null, m("ol", null, Object.keys(actionValidation).map(key => m("li", null, m("strong", null, key, ":"), " ", actionValidation[key].join('')))))));
    }
    const requirementValidation = criterion.invalidRequirementSettings();
    if (requirementValidation && Object.keys(requirementValidation).length) {
      messages.push(m(Alert, {
        type: "error",
        dismissible: false
      }, app.translator.trans('askvortsov-auto-moderator.admin.criterion_status.requirement_validation_errors'), m("div", null, m("ol", null, Object.keys(requirementValidation).map(key => m("li", null, m("strong", null, key, ":"), " ", requirementValidation[key].join('')))))));
    }
    if (criterion.metrics().length === 0 && criterion.requirements().length === 0) {
      messages.push(m(Alert, {
        type: "danger",
        dismissible: false
      }, app.translator.trans('askvortsov-auto-moderator.admin.criterion_status.no_metrics_or_reqs')));
    }
    if (criterion.actions().length === 0) {
      messages.push(m(Alert, {
        type: "danger",
        dismissible: false
      }, app.translator.trans('askvortsov-auto-moderator.admin.criterion_status.no_actions')));
    }
    return m("div", {
      className: "StatusCheck Form-group"
    }, m("label", null, app.translator.trans('askvortsov-auto-moderator.admin.criterion_status.heading')), messages);
  }
}
flarum.reg.add('askvortsov-auto-moderator', 'admin/components/CriterionStatus', CriterionStatus);