import Component from 'flarum/common/Component';
import GroupSelector from './GroupSelector';
export default class GroupActionDriverSettings extends Component {
  view() {
    const settings = this.attrs.settings;
    return m(GroupSelector, {
      value: settings().group_id,
      onchange: val => settings({
        group_id: val
      })
    });
  }
}
flarum.reg.add('askvortsov-auto-moderator', 'admin/components/GroupIdSelector', GroupActionDriverSettings);